// Final v0.3 reads the ability-screen art of graphics 61/62/200/201/207/208
// through six 8-byte cells at decoded TSR 0x6BA98 (RAM 0x20288A98), copies of
// the C_ROBOT header entries id*8. An added unit repacks C_ROBOT.BIN and root 1;
// the cells must follow, and a reopen must accept both the stock cells (older
// outputs) and the cells of the carried archive. The synthetic part uses
// generated bytes only. The golden part runs when SRWF_GOLDEN_IMAGE_DIR holds
// final-v0.3-{a,b,c}.bin (and SRWF_GOLDEN_SRW4_ROM a SRW4 Rev 1 ROM for the
// bulk import); it asserts offsets, hashes and record identity only.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {LEGACY_ROBOT_CELLS as P,legacyRobotCellsState,syncLegacyRobotCells,normalizeLegacyRobotCells,staleLegacyRobotCells} from '../assets/editor-legacy-robot-cells.mjs';

const be32=(bytes,at,value)=>new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength).setUint32(at,value>>>0);
const cells=decoded=>Array.from(decoded.subarray(P.cells,P.cells+48));
function header(seed){const h=new Uint8Array(8*369);for(let id=0;id<369;id++){be32(h,8*id,2952-8*id+seed*977+id*1301);be32(h,8*id+4,2952-8*id-4+seed*977+(id+1)*1301);}return h;}
function decoded(h){const d=new Uint8Array(0x6f0c8);for(let i=0;i<d.length;i++)d[i]=i*7&255;d.set(P.ids,P.table);P.ids.forEach((id,k)=>d.set(h.subarray(8*id,8*id+8),P.cells+8*k));return d;}
function exec(){const e=new Uint8Array(P.execBytes);be32(e,P.execTableLiteral,P.ramTable);be32(e,P.execCellsLiteral,P.ramCells);return e;}
const stock=header(0),moved=header(1),gameId='srwf-final';

test('the cell table maps exactly onto the RAM literals of the v0.3 EXEC',()=>{
 assert.deepEqual([...P.ids],[0x3d,0x3e,0xc8,0xc9,0xcf,0xd0]);
 assert.equal(P.ramTable-P.table,P.ramCells-P.cells);assert.equal(P.ramCells-P.cells,0x2021d000);
 assert.equal(P.execCellsLiteral+0x06004000,0x060ae434);
});

test('an unchanged archive leaves every TSR byte as it was',()=>{
 const d=decoded(stock),before=d.slice();
 assert.equal(syncLegacyRobotCells(d,stock,{gameId,exec:exec()}),false);
 assert.deepEqual(d,before);
 assert.equal(normalizeLegacyRobotCells(d,{gameId,originalHeader:stock,currentHeader:stock}),d);
 assert.deepEqual(staleLegacyRobotCells(d,stock,{gameId}),[]);
});

test('a repacked archive moves exactly the six cells to its header entries',()=>{
 const d=decoded(stock),before=d.slice();
 assert.deepEqual(staleLegacyRobotCells(d,moved,{gameId}),[...P.ids]);
 assert.equal(syncLegacyRobotCells(d,moved,{gameId,exec:exec()}),true);
 const changed=[...d.keys()].filter(i=>d[i]!==before[i]);
 assert.ok(changed.length>0&&changed.every(i=>i>=P.cells&&i<P.cells+48));
 P.ids.forEach((id,k)=>assert.deepEqual(Array.from(d.subarray(P.cells+8*k,P.cells+8*k+8)),Array.from(moved.subarray(8*id,8*id+8))));
 assert.deepEqual(staleLegacyRobotCells(d,moved,{gameId}),[]);
 assert.equal(syncLegacyRobotCells(d,moved,{gameId,exec:exec()}),false);
});

test('reopen accepts stock cells (earlier editor) and archive cells (this editor), restoring the stock bytes',()=>{
 const fixed=decoded(stock);syncLegacyRobotCells(fixed,moved,{gameId,exec:exec()});
 const canonical=normalizeLegacyRobotCells(fixed,{gameId,originalHeader:stock,currentHeader:moved});
 assert.notEqual(canonical,fixed);assert.deepEqual(canonical,decoded(stock));
 const old=decoded(stock);
 assert.equal(normalizeLegacyRobotCells(old,{gameId,originalHeader:stock,currentHeader:moved}),old);
 // One cell of each kind is also accepted.
 const mixed=decoded(stock);mixed.set(moved.subarray(8*201,8*201+8),P.cells+8*3);
 assert.deepEqual(normalizeLegacyRobotCells(mixed,{gameId,originalHeader:stock,currentHeader:moved}),decoded(stock));
 const foreign=fixed.slice();foreign[P.cells+8*3+7]^=1;
 assert.throws(()=>normalizeLegacyRobotCells(foreign,{gameId,originalHeader:stock,currentHeader:moved}),{code:'EDITOR_BATTLE_COMPONENT_INVALID'});
});

test('the cells are written only when the TSR id table and both EXEC literals agree',()=>{
 const d=decoded(stock);
 const wrongLiteral=exec();be32(wrongLiteral,P.execCellsLiteral,P.ramCells+8);
 for(const e of [null,wrongLiteral,new Uint8Array(P.execBytes)])
  assert.throws(()=>syncLegacyRobotCells(d,moved,{gameId,exec:e}),{code:'EDITOR_BATTLE_COMPONENT_INVALID'});
 const noTable=decoded(stock);noTable[P.table+2]^=1;
 assert.throws(()=>syncLegacyRobotCells(noTable,moved,{gameId,exec:exec()}),{code:'EDITOR_BATTLE_COMPONENT_INVALID'});
 // Neither side (another base, F, small synthetic TSRs): nothing to do.
 const before=noTable.slice();
 assert.equal(syncLegacyRobotCells(noTable,moved,{gameId,exec:null}),false);assert.deepEqual(noTable,before);
 assert.equal(syncLegacyRobotCells(new Uint8Array(4096),moved,{gameId,exec:null}),false);
 assert.equal(legacyRobotCellsState(d,{gameId:'srwf-f',exec:null}).present,false);
 assert.equal(syncLegacyRobotCells(d,moved,{gameId:'srwf-f',exec:null}),false);
 assert.equal(normalizeLegacyRobotCells(d,{gameId:'srwf-f',originalHeader:stock,currentHeader:moved}),d);
 assert.deepEqual(d,decoded(stock));
});

// -------- real images (optional) --------
const IMAGE_DIR=process.env.SRWF_GOLDEN_IMAGE_DIR,SRW4=process.env.SRWF_GOLDEN_SRW4_ROM;
const LANES=['a','b','c'].map(v=>`final-v0.3-${v}`).filter(lane=>IMAGE_DIR&&fs.existsSync(`${IMAGE_DIR}/${lane}.bin`));
if(LANES.length){
 const core=await import('../assets/editor-core.mjs');
 const {echoRequest}=await import('./helpers/synthetic-iso.mjs');
 const {planConceptUnitConstruction,replaceUnitRow}=await import('../assets/editor-unit-construction.mjs');
 const {unitWeaponFields,UNIT_WEAPON_FIELDS}=await import('../assets/editor-loadout.mjs');
 const {planSrw4UnusedImport}=await import('../assets/editor-srw4-unused.mjs');
 const {createHash}=await import('node:crypto');
 const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
 const i32=(b,o)=>(b[o]<<24|b[o+1]<<16|b[o+2]<<8|b[o+3])|0;
 const mode=async(blob,lba)=>new Uint8Array(await blob.slice(lba*2352+15,lba*2352+16).arrayBuffer())[0];
 const read=async(blob,f)=>core.readCdUserExtent(blob,f.extentLba,f.byteLength,{mode:await mode(blob,f.extentLba)});
 // Physical bytes as the game loads them: TSR (decoded) and C_ROBOT.
 async function physical(blob){
  const files=await core.locateIsoFiles(blob,undefined,['TSR.BIN','C_ROBOT.BIN']);
  return {tsr:core.decompressTsr(await read(blob,files.tsr)),robot:await read(blob,files.c_robot)};
 }
 const record=(robot,cell,id)=>{const c=8*id;return robot.subarray(c+i32(cell,0),c+4+i32(cell,4));};
 function assertCells(after,before){
  assert.deepEqual([...after.tsr.subarray(P.table,P.table+6)],[...P.ids]);
  P.ids.forEach((id,k)=>{
   const cell=after.tsr.subarray(P.cells+8*k,P.cells+8*k+8);
   assert.deepEqual([...cell],[...after.robot.subarray(8*id,8*id+8)],`cell ${id} follows the archive header`);
   assert.equal(sha(record(after.robot,cell,id)),sha(record(before.robot,before.tsr.subarray(P.cells+8*k,P.cells+8*k+8),id)),`graphic ${id} reads its own record`);
  });
 }
 function rows(opened){
  const units=structuredClone(opened.view.units),weapons=structuredClone(opened.view.weapons);
  units.forEach(r=>{Object.assign(r,unitWeaponFields(r.weaponList));r.original={...r};r.restorationEligible=opened.view.unitRestorationSlots.includes(r.recordIndex);r.weaponAdditions=[];});
  weapons.forEach(r=>r.original={...r});return {units,weapons};
 }
 function constructionRequest(opened,units,weapons){
  const request={...echoRequest(opened.session,{...opened.view,units,weapons}),
   unitRestorations:units.filter(r=>r.pendingConstruction).map(r=>({recordIndex:r.recordIndex,preset:r.pendingConstruction,loadoutVersion:r.construction.loadoutVersion})),
   weaponClones:weapons.filter(r=>r.pendingWeaponClone).map(r=>({recordIndex:r.recordIndex,sourceRecordIndex:r.weaponClone.sourceRecordIndex})),
   weaponNameEdits:weapons.filter(r=>r.pendingWeaponClone).map(r=>({recordIndex:r.recordIndex,text:r.name})),
   unitWeaponAdditions:units.filter(r=>r.weaponAdditions?.length).map(r=>({recordIndex:r.recordIndex,weapons:r.weaponAdditions}))};
  for(const e of request.unitEdits){const r=units.find(r=>r.recordIndex===e.recordIndex);for(const k of ['killMoney','killExp','partSlots',...UNIT_WEAPON_FIELDS])if(Number.isInteger(r[k]))e.fields[k]=r[k];}
  return request;
 }
 async function open(blob,targetSha256){return core.inspectPatchedImage(blob,{gameId:'srwf-final',targetSize:blob.size,targetSha256,imageKind:'local'},{});}
 async function reopenRoundTrip(output){
  const again=await open(output.outputBlob,output.sha256);
  const second=await core.exportEditedImage(again.session,echoRequest(again.session,again.view),{});
  assert.equal(second.sha256,output.sha256,'reopen and save without edits returns the same bytes');
 }
 for(const lane of LANES){
  const path=`${IMAGE_DIR}/${lane}.bin`;
  test(`golden ${lane}: a save without edits is byte-identical and the stock cells equal the archive header`,{timeout:600000},async()=>{
   const blob=await fs.openAsBlob(path),hash=createHash('sha256');for await(const chunk of fs.createReadStream(path))hash.update(chunk);
   const input=hash.digest('hex'),opened=await open(blob,input),before=await physical(blob);
   assertCells(before,before);
   const output=await core.exportEditedImage(opened.session,echoRequest(opened.session,opened.view),{});
   assert.equal(output.sha256,input);assert.equal(output.bytesChanged??0,0);
  });
  test(`golden ${lane}: an added 사일바인 moves the six ability-screen cells with C_ROBOT and reopens`,{timeout:600000},async()=>{
   const blob=await fs.openAsBlob(path),before=await physical(blob);
   const hash=createHash('sha256');for await(const chunk of fs.createReadStream(path))hash.update(chunk);
   const opened=await open(blob,hash.digest('hex')),{units,weapons}=rows(opened);
   const target=units.find(r=>r.restorationEligible&&!r.construction&&r.recordKind==='unused-filler');
   const plan=planConceptUnitConstruction(target,units,weapons,'sirbine','srwf-final');
   for(const update of plan.weaponUpdates)replaceUnitRow(weapons.find(w=>w.recordIndex===update.row.recordIndex),update.row);
   replaceUnitRow(target,plan.unit);
   const output=await core.exportEditedImage(opened.session,constructionRequest(opened,units,weapons),{});
   const after=await physical(output.outputBlob);
   assert.notDeepEqual([...after.robot.subarray(0,2952)],[...before.robot.subarray(0,2952)],'the archive was repacked');
   assertCells(after,before);
   await reopenRoundTrip(output);
  });
  test(`golden ${lane}: the SRW4 bulk import moves the six cells too`,{skip:!SRW4||!fs.existsSync(SRW4),timeout:900000},async()=>{
   const blob=await fs.openAsBlob(path),before=await physical(blob);
   const hash=createHash('sha256');for await(const chunk of fs.createReadStream(path))hash.update(chunk);
   const opened=await open(blob,hash.digest('hex')),{units,weapons}=rows(opened);
   const plan=planSrw4UnusedImport(units,weapons,'srwf-final');
   await core.attachSrw4EditorSource(opened.session,await core.prepareSrw4EditorSource(await fs.openAsBlob(SRW4)));
   const output=await core.exportEditedImage(opened.session,{...constructionRequest(opened,plan.units,plan.weapons),srw4Native:true},{});
   assertCells(await physical(output.outputBlob),before);
   await reopenRoundTrip(output);
  });
 }
}
